select a.* from (
SELECT
/***update by leipeng 20200628**/
CC.REGIST_BANK_CODE issuePartyId, /*发行机构代码*/
POS.ISSUE_PARTY_ID as issuePartyId,
POS_DATE as posDate, POS.PLAN_ASSET_ID as planAssetId, POS.ASSET_CODE as assetCode, POS.TOTAL_NUM as totalNum, POS.ISSUE_AMT as issueAmt, POS.UNINVEST_CASH as uninvestCash, POS.POS_NUM as posNum, POS.POS_AMT as posAmt, POS.ORG_CODE as orgCode, POS.DEPT_CODE as deptCode, POS.CREATE_USER as createUser, POS.CREATE_TIME as createTime, POS.UPDATE_USER as updateUser, POS.UPDATE_TIME as updateTime, POS.CHB_SUBMIT_DEADLINE as chbSubmitDeadline, POS.SUBMIT_DEADLINE as submitDeadline, POS.SEND_STATUS as sendStatus, POS.SUBMIT_TIME as submitTime, POS.REGIST_SEQNO registSeqno, POS.STATUS_DATE as statusDate, POS.STATUS as status, POS.SUBMIT_FEEDBACK_STATUS as submitFeedbackStatus FROM CHB_BOT_AST_POS_SUB POS
LEFT JOIN DATA_AUTH_NOTIFY_INST DI ON (DI.BUSINESS_ID = POS.PLAN_ASSET_ID or (di.BUSINESS_ID = 'F28_' || POS.PLAN_ASSET_ID )) AND DI.MODEL_TYPE = '02' AND DI.DATA_TYPE in ( 'PTL01','FINASSET12') LEFT JOIN CHB_ORG_REGIST_BANK_CODE CC ON DI.BELONG_INSTITUTION_CODE=cc.org_code
DATE_FORMAT(POS.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{submitDeadLineStart,jdbcType=VARCHAR}
and DATE_FORMAT(POS.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{submitDeadLineEnd,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
and DATE_FORMAT(POS.STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart,jdbcType=VARCHAR}
and DATE_FORMAT(POS.STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd,jdbcType=VARCHAR}
and DATE_FORMAT(POS.SUBMIT_TIME,'%Y-%m-%d') >= #{submitDateStart,jdbcType=VARCHAR}
and DATE_FORMAT(POS.SUBMIT_TIME,'%Y-%m-%d') <= #{submitDateEnd,jdbcType=VARCHAR}
and DATE_FORMAT(POS.POS_DATE,'%Y-%m-%d') >= #{posDateStart,jdbcType=VARCHAR}
and DATE_FORMAT(POS.POS_DATE,'%Y-%m-%d') <= #{posDateEnd,jdbcType=VARCHAR}
#{submitFeedbackStatus,jdbcType=VARCHAR}
and upper(POS.ASSET_CODE) like CONCAT(CONCAT('%',upper(#{assetCodeLike,jdbcType=VARCHAR})),'%')
and upper(POS.PLAN_ASSET_ID) like CONCAT(CONCAT('%',upper(#{planAssetIdLike,jdbcType=VARCHAR})),'%')
) a order by posDate,planAssetId

select a.* from
(



			1=1

				and trim(POS.REGIST_SEQNO) = #{regist.registSeqno}


				and POS.STATUS = #{regist.status}


				and POS.SEND_STATUS = #{regist.sendStatus}


				and POS.REGIST_BANK_CODE = #{regist.registBankCode}




) a

select a.* from (SELECT
/***update by leipeng 20200628**/
CC.REGIST_BANK_CODE issuePartyId, /*发行机构代码*/
POS.ISSUE_PARTY_ID as issuePartyId,
POS_DATE as posDate, POS.PLAN_ASSET_ID as planAssetId, POS.ASSET_CODE as assetCode, POS.TOTAL_NUM as totalNum, POS.ISSUE_AMT as issueAmt, POS.UNINVEST_CASH as uninvestCash, POS.POS_NUM as posNum, POS.POS_AMT as posAmt, POS.ORG_CODE as orgCode, POS.DEPT_CODE as deptCode, POS.CREATE_USER as createUser, POS.CREATE_TIME as createTime, POS.UPDATE_USER as updateUser, POS.UPDATE_TIME as updateTime, POS.CHB_SUBMIT_DEADLINE as chbSubmitDeadline, POS.SUBMIT_DEADLINE as submitDeadline, POS.SEND_STATUS as sendStatus, POS.SUBMIT_TIME as submitTime, POS.REGIST_SEQNO registSeqno, POS.STATUS_DATE as statusDate, POS.STATUS as status, POS.SUBMIT_FEEDBACK_STATUS as submitFeedbackStatus FROM CHB_BOT_AST_POS_SUB POS
LEFT JOIN DATA_AUTH_NOTIFY_INST DI ON DI.BUSINESS_ID = POS.PLAN_ASSET_ID AND DI.MODEL_TYPE = '02' AND DATA_TYPE = 'PTL01' LEFT JOIN CHB_ORG_REGIST_BANK_CODE CC ON DI.BELONG_INSTITUTION_CODE=cc.org_code
1=1
and trim(POS.REGIST_SEQNO) = #{regist.registSeqno}
