select REGIST_SEQNO
from
(select * from CHB_BOT_AST_POS_SUB
where 1=1

	and SEND_STATUS in ('02','03')


	and SEND_STATUS = '01'

)as t


		t.POS_DATE = #{item.posDate}
		and t.PLAN_ASSET_ID = #{item.planAssetId}
		and t.ASSET_CODE = #{item.assetCode}
		and t.REGIST_SEQNO != #{item.registSeqno}
